
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_df3_opt1_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_df3_opt1", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.239106238659508e+00, -4.156253465287280e+00, -4.040204538505397e+00, -3.879549040490404e+00, -3.660851200169678e+00, -3.370246776663630e+00, -2.997231882078559e+00, -2.541567136795538e+00, -2.022961730185573e+00, -1.488357999810911e+00, -1.001318424589109e+00, -6.917288377528072e-01, -5.963253866991625e-01, -4.876991418633860e-01, -3.492320235465748e-01, -2.210376656431031e-01, -1.306864890633904e-01, -7.799117622446460e-02, -4.877574684151659e-02, -3.297347520985364e-02]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


